{
  "query": "query GetProfile($id: ID!) { profile(id: $id) { id username email displayName status version createdAt updatedAt } }",
  "variables": { "id": "{{profile_id}}" }
}

{
  "query": "query SearchProfiles($query: String, $status: ProfileStatus, $limit: Int, $offset: Int) { searchProfiles(query: $query, status: $status, limit: $limit, offset: $offset) { total items { id username displayName status version } } }",
  "variables": { "query": "", "limit": 20, "offset": 0 }
}

{
  "query": "mutation CreateProfile($input: CreateProfileInput!) { createProfile(input: $input) { profile { id username email displayName status version } accessToken } }",
  "variables": {
    "input": {
      "username": "postman_user",
      "email": "postman@example.com",
      "displayName": "Postman User"
    }
  }
}

{
  "query": "mutation UpdateProfile($input: UpdateProfileInput!) { updateProfile(input: $input) { id displayName version status } }",
  "variables": {
    "input": {
      "id": "{{profile_id}}",
      "version": {{profile_version}},
      "displayName": "Postman Updated"
    }
  }
}

{
  "query": "mutation { createProfile(input: { username: \"a\", email: \"x@example.com\", displayName: \"X\" }) { profile { id } accessToken } }"
}

{
  "query": "mutation { updateProfile(input: { id: \"{{profile_id}}\", version: {{profile_version}}, displayName: \"No token\" }) { id } }"
}

{
  "query": "mutation { updateProfile(input: { id: \"not-my-profile-id\", version: 1, displayName: \"Hijack attempt\" }) { id } }"
}
